// Calculate staleness signals for each knowledge base article
const items = $input.all();
const outputItems = [];

for (const item of items) {
  const article = item.json;

  // Calculate days since last update
  const lastUpdated = new Date(article.updated_at || article.created_at);
  const now = new Date();
  const daysSinceUpdate = Math.floor((now - lastUpdated) / (1000 * 60 * 60 * 24));

  // Calculate view trend (comparing recent vs older views)
  const viewsLast30Days = article.views_last_30_days || 0;
  const viewsPrevious30Days = article.views_previous_30_days || 0;
  const viewTrend = viewsPrevious30Days > 0 
    ? ((viewsLast30Days - viewsPrevious30Days) / viewsPrevious30Days) * 100 
    : 0;

  // Calculate engagement metrics
  const totalViews = article.total_views || 0;
  const helpfulVotes = article.helpful_votes || 0;
  const unhelpfulVotes = article.unhelpful_votes || 0;
  const totalVotes = helpfulVotes + unhelpfulVotes;
  const helpfulnessRatio = totalVotes > 0 ? (helpfulVotes / totalVotes) * 100 : 50;

  // Calculate staleness score (0-100, higher = more stale)
  let stalenessScore = 0;

  // Age factor (0-40 points)
  if (daysSinceUpdate > 365) stalenessScore += 40;
  else if (daysSinceUpdate > 180) stalenessScore += 30;
  else if (daysSinceUpdate > 90) stalenessScore += 20;
  else if (daysSinceUpdate > 30) stalenessScore += 10;

  // View trend factor (0-30 points)
  if (viewTrend < -50) stalenessScore += 30;
  else if (viewTrend < -25) stalenessScore += 20;
  else if (viewTrend < 0) stalenessScore += 10;

  // Helpfulness factor (0-30 points)
  if (helpfulnessRatio < 30) stalenessScore += 30;
  else if (helpfulnessRatio < 50) stalenessScore += 20;
  else if (helpfulnessRatio < 70) stalenessScore += 10;

  outputItems.push({
    json: {
      ...article,
      staleness_signals: {
        days_since_update: daysSinceUpdate,
        view_trend_percent: Math.round(viewTrend * 10) / 10,
        helpfulness_ratio: Math.round(helpfulnessRatio * 10) / 10,
        staleness_score: stalenessScore,
        views_last_30_days: viewsLast30Days,
        views_previous_30_days: viewsPrevious30Days,
        total_votes: totalVotes
      }
    }
  });
}

return outputItems;

// Filter articles with staleness score above threshold and extract version references
const items = $input.all();
const outputItems = [];

// Get threshold from configuration
const thresholdDays = $('Set Workflow Configuration').first().json.stalenessThresholdDays || 90;
const currentVersion = $('Set Workflow Configuration').first().json.currentProductVersion || '';

for (const item of items) {
  const article = item.json;
  const stalenessSignals = article.staleness_signals || {};
  const stalenessScore = stalenessSignals.staleness_score || 0;
  const daysSinceUpdate = stalenessSignals.days_since_update || 0;

  // Filter: Only include articles that exceed staleness threshold
  if (daysSinceUpdate >= thresholdDays || stalenessScore >= 50) {

    // Extract version references from article content
    const content = article.content || article.body || '';
    const versionPattern = /\b(v?\d+\.\d+(?:\.\d+)?(?:\.\d+)?)\b/gi;
    const versionMatches = content.match(versionPattern) || [];
    const uniqueVersions = [...new Set(versionMatches.map(v => v.toLowerCase()))];

    // Check if article references outdated versions
    const hasOutdatedVersions = uniqueVersions.some(v => {
      const cleanVersion = v.replace(/^v/, '');
      return cleanVersion !== currentVersion && cleanVersion < currentVersion;
    });

    outputItems.push({
      json: {
        ...article,
        staleness_analysis: {
          staleness_score: stalenessScore,
          days_since_update: daysSinceUpdate,
          exceeds_threshold: true,
          version_references: uniqueVersions,
          has_outdated_versions: hasOutdatedVersions,
          current_product_version: currentVersion,
          threshold_days: thresholdDays
        }
      }
    });
  }
}

return outputItems;

