// Build comprehensive weekly report with summary statistics and detailed breakdowns
const items = $input.all();
const results = items[0].json.results || [];

// Initialize counters
let totalArticlesProcessed = 0;
let articlesAutoUpdated = 0;
let articlesRequiringSME = 0;
let knowledgeGapsIdentified = 0;
const staleArticles = [];
const autoUpdatedArticles = [];
const smeReviewQueue = [];
const knowledgeGaps = [];

// Process results
for (const result of results) {
  totalArticlesProcessed++;

  // Check if article was auto-updated
  if (result.reviewType !== 'SME_REQUIRED' && result.updateComplexity === 'minor') {
    articlesAutoUpdated++;
    autoUpdatedArticles.push({
      title: result.articleTitle || result.title,
      id: result.articleId || result.id,
      stalenessScore: result.staleness_signals?.staleness_score || 0,
      daysSinceUpdate: result.staleness_signals?.days_since_update || 0
    });
  }

  // Check if article requires SME review
  if (result.reviewType === 'SME_REQUIRED' || result.updateComplexity === 'major') {
    articlesRequiringSME++;
    smeReviewQueue.push({
      title: result.articleTitle || result.title,
      id: result.articleId || result.id,
      reason: result.reviewReason || result.suggestedUpdates,
      priority: result.priority || 'medium',
      stalenessScore: result.staleness_signals?.staleness_score || 0
    });
  }

  // Track stale articles
  if (result.staleness_signals?.staleness_score >= 50) {
    staleArticles.push({
      title: result.articleTitle || result.title,
      id: result.articleId || result.id,
      stalenessScore: result.staleness_signals.staleness_score,
      daysSinceUpdate: result.staleness_signals.days_since_update,
      viewTrend: result.staleness_signals.view_trend_percent
    });
  }

  // Collect knowledge gaps
  if (result.knowledgeGaps && Array.isArray(result.knowledgeGaps)) {
    knowledgeGapsIdentified += result.knowledgeGaps.length;
    knowledgeGaps.push(...result.knowledgeGaps);
  }
}

// Sort arrays by priority/score
staleArticles.sort((a, b) => b.stalenessScore - a.stalenessScore);
smeReviewQueue.sort((a, b) => {
  const priorityOrder = { high: 3, medium: 2, low: 1 };
  return (priorityOrder[b.priority] || 0) - (priorityOrder[a.priority] || 0);
});

// Build report sections
const reportDate = new Date().toISOString().split('T')[0];

const summarySection = `📊 *Knowledge Base Auto-Maintenance Weekly Report*
_Report Date: ${reportDate}_

*Summary Statistics:*
• Total Articles Processed: ${totalArticlesProcessed}
• Articles Auto-Updated: ${articlesAutoUpdated}
• Articles Requiring SME Review: ${articlesRequiringSME}
• Knowledge Gaps Identified: ${knowledgeGapsIdentified}
• Stale Articles Detected: ${staleArticles.length}
`;

const autoUpdatedSection = articlesAutoUpdated > 0 ? `

✅ *Auto-Updated Articles (${articlesAutoUpdated}):*
${autoUpdatedArticles.slice(0, 10).map((article, idx) => 
  `${idx + 1}. ${article.title} (Score: ${article.stalenessScore}, ${article.daysSinceUpdate} days old)`
).join('\n')}${autoUpdatedArticles.length > 10 ? `\n... and ${autoUpdatedArticles.length - 10} more` : ''}
` : '';

const smeReviewSection = articlesRequiringSME > 0 ? `

⚠️ *SME Review Required (${articlesRequiringSME}):*
${smeReviewQueue.slice(0, 10).map((article, idx) => 
  `${idx + 1}. [${article.priority.toUpperCase()}] ${article.title}\n   Reason: ${article.reason?.substring(0, 100)}...`
).join('\n\n')}${smeReviewQueue.length > 10 ? `\n... and ${smeReviewQueue.length - 10} more` : ''}
` : '';

const staleArticlesSection = staleArticles.length > 0 ? `

🕒 *Top Stale Articles (${staleArticles.length}):*
${staleArticles.slice(0, 10).map((article, idx) => 
  `${idx + 1}. ${article.title}\n   Staleness Score: ${article.stalenessScore}/100 | ${article.daysSinceUpdate} days old | View Trend: ${article.viewTrend}%`
).join('\n\n')}${staleArticles.length > 10 ? `\n... and ${staleArticles.length - 10} more` : ''}
` : '';

const knowledgeGapsSection = knowledgeGapsIdentified > 0 ? `

🔍 *Knowledge Gaps Identified (${knowledgeGapsIdentified}):*
${knowledgeGaps.slice(0, 10).map((gap, idx) => 
  `${idx + 1}. [${gap.priority?.toUpperCase() || 'MEDIUM'}] ${gap.topic}\n   Suggested Article: "${gap.suggestedArticleTitle}"\n   Support Tickets: ${gap.ticketCount || 0}`
).join('\n\n')}${knowledgeGaps.length > 10 ? `\n... and ${knowledgeGaps.length - 10} more` : ''}
` : '';

const actionItemsSection = `

📋 *Action Items:*
${articlesRequiringSME > 0 ? `• Review ${articlesRequiringSME} articles flagged for SME attention\n` : ''}${knowledgeGapsIdentified > 0 ? `• Create ${knowledgeGapsIdentified} new articles to address knowledge gaps\n` : ''}${staleArticles.length > 0 ? `• Monitor ${staleArticles.length} stale articles for potential updates\n` : ''}• Review auto-updated articles for quality assurance
`;

const fullReport = summarySection + autoUpdatedSection + smeReviewSection + staleArticlesSection + knowledgeGapsSection + actionItemsSection;

return [{
  json: {
    reportDate,
    reportText: fullReport,
    summary: {
      totalArticlesProcessed,
      articlesAutoUpdated,
      articlesRequiringSME,
      knowledgeGapsIdentified,
      staleArticlesCount: staleArticles.length
    },
    autoUpdatedArticles,
    smeReviewQueue,
    staleArticles,
    knowledgeGaps
  }
}];

// Extract all URLs from article content and prepare them for validation
const item = $input.item.json;
const content = item.content || item.body || '';

// Regular expression to match URLs (http, https, and relative URLs)
const urlRegex = /(https?:\/\/[^\s<>"{}|\\^`\[\]]+)|(\/[^\s<>"{}|\\^`\[\]]*)/gi;
const matches = content.match(urlRegex) || [];

// Remove duplicates and filter out empty matches
const uniqueUrls = [...new Set(matches)].filter(url => url && url.length > 1);

// Categorize URLs
const externalUrls = [];
const internalUrls = [];
const relativeUrls = [];

for (const url of uniqueUrls) {
  if (url.startsWith('http://') || url.startsWith('https://')) {
    // Check if it's an internal or external URL
    const knowledgeBaseUrl = $('Set Workflow Configuration').first().json.knowledgeBaseApiUrl || '';
    const baseDomain = knowledgeBaseUrl.replace(/^https?:\/\//, '').split('/')[0];

    if (url.includes(baseDomain)) {
      internalUrls.push(url);
    } else {
      externalUrls.push(url);
    }
  } else if (url.startsWith('/')) {
    relativeUrls.push(url);
  }
}

return {
  json: {
    ...item,
    extracted_links: {
      total_links: uniqueUrls.length,
      external_urls: externalUrls,
      internal_urls: internalUrls,
      relative_urls: relativeUrls,
      all_urls: uniqueUrls
    }
