// Calculate comprehensive quality score based on multiple factors
const items = $input.all();
const outputItems = [];

for (const item of items) {
  const article = item.json;

  // Initialize quality score components (0-100 scale for each)
  let stalenessScore = 0;
  let linkHealthScore = 100;
  let sentimentScore = 100;
  let factualAccuracyScore = 100;

  // 1. Staleness Score (inverse - lower staleness = higher quality)
  const staleness = article.staleness_signals?.staleness_score || 0;
  stalenessScore = Math.max(0, 100 - staleness);

  // 2. Link Health Score
  const linkAnalysis = article.link_analysis || {};
  const totalLinks = linkAnalysis.total_links || 0;
  const brokenLinks = linkAnalysis.broken_links || 0;

  if (totalLinks > 0) {
    const brokenLinkRatio = brokenLinks / totalLinks;
    linkHealthScore = Math.max(0, 100 - (brokenLinkRatio * 100));
  }

  // 3. Sentiment Score (based on user feedback)
  const feedbackSentiment = article.feedback_sentiment || {};
  const positiveCount = feedbackSentiment.positive || 0;
  const negativeCount = feedbackSentiment.negative || 0;
  const neutralCount = feedbackSentiment.neutral || 0;
  const totalFeedback = positiveCount + negativeCount + neutralCount;

  if (totalFeedback > 0) {
    const positiveRatio = positiveCount / totalFeedback;
    const negativeRatio = negativeCount / totalFeedback;
    sentimentScore = (positiveRatio * 100) - (negativeRatio * 50);
    sentimentScore = Math.max(0, Math.min(100, sentimentScore));
  }

  // 4. Factual Accuracy Score
  const factCheck = article.fact_check || {};
  const totalClaims = factCheck.total_claims || 0;
  const accurateClaims = factCheck.accurate_claims || 0;
  const inaccurateClaims = factCheck.inaccurate_claims || 0;

  if (totalClaims > 0) {
    const accuracyRatio = accurateClaims / totalClaims;
    const inaccuracyRatio = inaccurateClaims / totalClaims;
    factualAccuracyScore = (accuracyRatio * 100) - (inaccuracyRatio * 100);
    factualAccuracyScore = Math.max(0, Math.min(100, factualAccuracyScore));
  }

  // Calculate weighted overall quality score
  // Weights: Staleness (30%), Link Health (20%), Sentiment (25%), Factual Accuracy (25%)
  const overallQualityScore = Math.round(
    (stalenessScore * 0.30) +
    (linkHealthScore * 0.20) +
    (sentimentScore * 0.25) +
    (factualAccuracyScore * 0.25)
  );

  // Determine quality grade
  let qualityGrade = 'F';
  if (overallQualityScore >= 90) qualityGrade = 'A';
  else if (overallQualityScore >= 80) qualityGrade = 'B';
  else if (overallQualityScore >= 70) qualityGrade = 'C';
  else if (overallQualityScore >= 60) qualityGrade = 'D';

  // Identify quality issues
  const qualityIssues = [];
  if (stalenessScore < 70) qualityIssues.push('High staleness detected');
  if (linkHealthScore < 80) qualityIssues.push('Broken or outdated links');
  if (sentimentScore < 70) qualityIssues.push('Negative user feedback');
  if (factualAccuracyScore < 90) qualityIssues.push('Factual accuracy concerns');

  outputItems.push({
    json: {
      ...article,
      quality_score: {
        overall_score: overallQualityScore,
        grade: qualityGrade,
        components: {
          staleness_score: Math.round(stalenessScore),
          link_health_score: Math.round(linkHealthScore),
          sentiment_score: Math.round(sentimentScore),
          factual_accuracy_score: Math.round(factualAccuracyScore)
        },
        metrics: {
          total_links: totalLinks,
          broken_links: brokenLinks,
          total_feedback: totalFeedback,
          positive_feedback: positiveCount,
          negative_feedback: negativeCount,
          total_claims: totalClaims,
          accurate_claims: accurateClaims,
          inaccurate_claims: inaccurateClaims
        },
        issues: qualityIssues,
        requires_attention: overallQualityScore < 70
      }
    }
  });
}

return outputItems;

