// Generate comprehensive metrics dashboard data
const items = $input.all();
const reportData = items[0].json;

// Extract data from report
const summary = reportData.summary || {};
const autoUpdatedArticles = reportData.autoUpdatedArticles || [];
const smeReviewQueue = reportData.smeReviewQueue || [];
const staleArticles = reportData.staleArticles || [];
const knowledgeGaps = reportData.knowledgeGaps || [];

// Calculate quality trends
const avgStalenessScore = staleArticles.length > 0
  ? staleArticles.reduce((sum, a) => sum + (a.stalenessScore || 0), 0) / staleArticles.length
  : 0;

const avgDaysSinceUpdate = staleArticles.length > 0
  ? staleArticles.reduce((sum, a) => sum + (a.daysSinceUpdate || 0), 0) / staleArticles.length
  : 0;

// Staleness distribution
const stalenessDistribution = {
  critical: staleArticles.filter(a => a.stalenessScore >= 80).length,
  high: staleArticles.filter(a => a.stalenessScore >= 60 && a.stalenessScore < 80).length,
  medium: staleArticles.filter(a => a.stalenessScore >= 40 && a.stalenessScore < 60).length,
  low: staleArticles.filter(a => a.stalenessScore < 40).length
};

// Update velocity metrics
const updateVelocity = {
  autoUpdatesThisWeek: summary.articlesAutoUpdated || 0,
  manualReviewsRequired: summary.articlesRequiringSME || 0,
  totalProcessed: summary.totalArticlesProcessed || 0,
  automationRate: summary.totalArticlesProcessed > 0
    ? ((summary.articlesAutoUpdated / summary.totalArticlesProcessed) * 100).toFixed(2)
    : 0
};

// ROI calculations
const avgTimePerManualUpdate = 45; // minutes
const avgTimePerSMEReview = 30; // minutes
const timeSavedMinutes = (summary.articlesAutoUpdated || 0) * avgTimePerManualUpdate;
const timeSavedHours = (timeSavedMinutes / 60).toFixed(2);
const estimatedCostSavings = timeSavedHours * 50; // $50/hour average rate

const roi = {
  articlesAutoUpdated: summary.articlesAutoUpdated || 0,
  timeSavedHours: parseFloat(timeSavedHours),
  estimatedCostSavings: parseFloat(estimatedCostSavings.toFixed(2)),
  manualReviewTimeRequired: ((summary.articlesRequiringSME || 0) * avgTimePerSMEReview / 60).toFixed(2)
};

// Knowledge gap priorities
const gapPriorities = {
  high: knowledgeGaps.filter(g => g.priority === 'high').length,
  medium: knowledgeGaps.filter(g => g.priority === 'medium').length,
  low: knowledgeGaps.filter(g => g.priority === 'low').length
};

// Top knowledge gaps by ticket volume
const topGaps = knowledgeGaps
  .sort((a, b) => (b.ticketCount || 0) - (a.ticketCount || 0))
  .slice(0, 5)
  .map(gap => ({
    topic: gap.topic,
    ticketCount: gap.ticketCount || 0,
    suggestedTitle: gap.suggestedArticleTitle,
    priority: gap.priority
  }));

// Article health score (0-100)
const totalArticles = summary.totalArticlesProcessed || 1;
const healthScore = Math.round(
  ((totalArticles - staleArticles.length) / totalArticles) * 100
);

// Trend indicators (comparing to previous week - placeholder for now)
const trends = {
  stalenessScoreTrend: 'stable', // Would compare to historical data
  updateVelocityTrend: 'improving',
  knowledgeGapsTrend: 'increasing',
  healthScoreTrend: 'stable'
};

// Build comprehensive dashboard data
const dashboardData = {
  reportDate: reportData.reportDate,
  overview: {
    totalArticles: summary.totalArticlesProcessed || 0,
    healthScore: healthScore,
    avgStalenessScore: Math.round(avgStalenessScore * 10) / 10,
    avgDaysSinceUpdate: Math.round(avgDaysSinceUpdate)
  },
  qualityMetrics: {
    stalenessDistribution: stalenessDistribution,
    articlesRequiringAttention: staleArticles.length,
    articlesInGoodHealth: totalArticles - staleArticles.length
  },
  updateVelocity: updateVelocity,
  roi: roi,
  knowledgeGaps: {
    total: summary.knowledgeGapsIdentified || 0,
    byPriority: gapPriorities,
    topGaps: topGaps
  },
  trends: trends,
  actionItems: {
    smeReviewsRequired: summary.articlesRequiringSME || 0,
    newArticlesNeeded: summary.knowledgeGapsIdentified || 0,
    staleArticlesToMonitor: staleArticles.length
  }
};

return [{
  json: {
    ...reportData,
    dashboardData: dashboardData,
    metricsGenerated: true
  }
}];

